export const SEGMENT_MS = 6000;

/**
 * The gesture guide as designed hints instead of a table: each gesture is a small pictogram of the phone with the
 * hand's move drawn on it, its name, and its twins — the button and the keys, set as keycaps. Pictograms are
 * decorative; every hint is real text in a list.
 */
import type { ReactNode } from 'react';
import styles from './styles.module.css';

const Phone = ({ children }: { children: ReactNode }) => (
  <svg viewBox="0 0 56 72" className={styles.hintArt} aria-hidden="true" focusable="false">
    <rect x="12" y="4" width="32" height="60" rx="6" className={styles.hintPhone} />
    <path d="M17 10h22" className={styles.hintSeg} />
    {children}
  </svg>
);

const HINTS = [
  {
    id: 'tap', title: 'Tap the sides', twin: <>Previous / Next card buttons, or <span className={styles.keyset}><kbd>←</kbd> <kbd>→</kbd></span></>,
    art: (
      <Phone>
        <rect x="13.5" y="14" width="9" height="48" className={styles.hintZoneBack} />
        <rect x="22.5" y="14" width="20" height="48" className={styles.hintZone} />
        <circle cx="34" cy="38" r="5" className={styles.hintTouch} /><circle cx="34" cy="38" r="9" className={styles.hintRing} />
      </Phone>
    ),
  },
  {
    id: 'hold', title: 'Press and hold', twin: <>The Pause button, or <kbd>Space</kbd></>,
    art: (
      <Phone>
        <circle cx="28" cy="38" r="5" className={styles.hintTouch} /><circle cx="28" cy="38" r="10" className={styles.hintRing} /><circle cx="28" cy="38" r="14.5" className={styles.hintRing} />
        <path d="M24 19v6M29 19v6" className={styles.hintStroke} />
      </Phone>
    ),
  },
  {
    id: 'swipe', title: 'Swipe sideways', twin: <>Account buttons, or <span className={styles.keyset}><kbd>Shift</kbd> + <kbd>←</kbd> <kbd>→</kbd></span></>,
    art: (
      <Phone>
        <path d="M40 38H18M23 33l-5 5 5 5" className={styles.hintStroke} />
        <circle cx="40" cy="38" r="5" className={styles.hintTouch} />
      </Phone>
    ),
  },
  {
    id: 'down', title: 'Swipe down', twin: <>The Close button, or <kbd>Esc</kbd></>,
    art: (
      <Phone>
        <path d="M28 22v26M23 43l5 5 5-5" className={styles.hintStroke} />
        <circle cx="28" cy="22" r="5" className={styles.hintTouch} />
      </Phone>
    ),
  },
] as const;

export function Hints() {
  return (
    <ul className={styles.hints}>
      {HINTS.map((h) => (
        <li key={h.id} className={styles.hint}>
          {h.art}
          <div>
            <h4 className={styles.hintTitle}>{h.title}</h4>
            <p className={styles.hintTwin}>{h.twin}</p>
          </div>
        </li>
      ))}
    </ul>
  );
}

/* Port Ellery stories — "harbour signal flags": flat primary fields (signal red, flag yellow, navy, blue) with
   chunky grotesque numerals, the town spelled in flags, and a viewer that is a dark harbour-night frame. */
@property --pe-glow { syntax: '<color>'; inherits: true; initial-value: #2a3f73; }
.root {
  --pe-shadow: 27 32 48;
  --pe-rest: 0 1px 1px rgb(var(--pe-shadow) / 0.08), 1px 5px 14px -6px rgb(var(--pe-shadow) / 0.22);
  --pe-lift: 0 1px 1px rgb(var(--pe-shadow) / 0.05), 3px 14px 28px -10px rgb(var(--pe-shadow) / 0.36);
  --pe-navy: #1b2a4e;
  --pe-red: #c8262c;     /* paper text 5.3:1 */
  --pe-yellow: #f2c230;  /* navy text 8.4:1 */
  --pe-blue: #2456a6;    /* paper text 6.8:1 */
  --pe-paper: #fbfaf6;
  --pe-mist: #d5dcec;    /* secondary text on navy, 10.3:1 */
  --pe-accent: #b3202a;  /* small accent text on the page, ≥ 5.29:1 */
  position: relative;
  min-height: 100dvh;
  background: var(--mk-bg);
  color: var(--mk-ink);
  font-family: var(--mk-font-text);
}
:global([data-theme='dark']) .root { --pe-accent: #ff8a80; --pe-shadow: 0 0 0; }
/* Phones: one column. Wide containers: the tray and the hints on the left, the embedded story on a lit stage. */
.page { display: grid; gap: 0 56px; max-width: 1180px; margin: 0 auto; padding: 0 16px 56px; }
.lead { min-width: 0; }
@container (min-width: 64rem) {
  .page { grid-template-columns: minmax(0, 1fr) minmax(360px, 430px); align-items: start; padding-inline: 32px; }
  .embedSection { grid-column: 2; grid-row: 1; position: sticky; top: 60px; }
  .footer { grid-column: 1 / -1; }
}
.small { margin: 0; font-size: 0.8125rem; line-height: 1.5; color: var(--mk-ink-muted); }
.h3 { margin: 0; font-family: var(--mk-font-display); font-size: 1.25rem; font-weight: 700; letter-spacing: -0.015em; }

.masthead { padding: 28px 0 22px; border-bottom: 3px solid var(--mk-ink); }
.banner { display: block; width: min(100%, 288px); height: auto; color: var(--mk-ink-muted); }
.town { margin: 14px 0 0; font-family: var(--mk-font-display); font-size: clamp(3.25rem, 2.2rem + 6cqi, 5.75rem); font-weight: 800; line-height: 0.9; letter-spacing: -0.05em; }
.tagline { margin: 12px 0 0; max-width: 32ch; font-family: var(--mk-font-serif); font-size: 1.375rem; line-height: 1.25; text-wrap: pretty; }
.sample { margin: 14px 0 0; font-size: 0.8125rem; color: var(--mk-ink-muted); }
.sample > :first-child { margin-right: 8px; color: var(--pe-accent); }

.traySection { padding: 22px 0 6px; }
.trayHead { display: flex; flex-wrap: wrap; justify-content: space-between; align-items: baseline; gap: 4px 16px; margin-bottom: 12px; }
.tray { display: flex; gap: 12px; margin: 0 -16px; padding: 6px 16px 14px; overflow-x: auto; overscroll-behavior-x: contain; scroll-snap-type: x proximity; scroll-padding-inline: 16px; list-style: none; scrollbar-width: thin; }
.tray li { flex: none; scroll-snap-align: start; }
/* position: relative keeps the visually-hidden text inside the scroller (an absolute child would escape its clip). */
.ring { position: relative; display: grid; justify-items: center; gap: 4px; width: 88px; padding: 4px 0 6px; border: 0; border-radius: var(--mk-radius-m); background: none; color: inherit; font: inherit; text-align: center; cursor: pointer; }
.ringArt {
  display: grid; place-items: center; box-sizing: border-box; width: 76px; height: 76px; padding: 3px; border-radius: 50%;
  background: conic-gradient(var(--pe-red) 0 25%, var(--pe-yellow) 0 50%, var(--pe-blue) 0 75%, var(--pe-navy) 0 100%);
  box-shadow: var(--pe-rest);
  transition: transform var(--pe-press-dur) var(--pe-press), box-shadow var(--pe-press-dur) var(--pe-press);
}
@media (hover: hover) { .ring:hover .ringArt { transform: translateY(-3px) scale(1.04); box-shadow: var(--pe-lift); } }
.ring:active .ringArt { transform: scale(0.94); box-shadow: 0 0 1px rgb(var(--pe-shadow) / 0.4); transition-duration: var(--mk-duration-instant); }
.ring[data-seen] .ringArt { padding: 1.5px; background: var(--mk-line-strong); }
.ringFlag { box-sizing: border-box; width: 100%; height: 100%; padding: 16px 12px; border: 3px solid var(--mk-bg); border-radius: 50%; background: var(--mk-surface); }
.ring:hover .ringFlag { background: var(--mk-surface-2); }
.ringName { max-width: 88px; font-size: 0.75rem; font-weight: 600; line-height: 1.2; }
.ringState { font-family: var(--mk-font-mono); font-size: 0.625rem; letter-spacing: 0.06em; text-transform: uppercase; color: var(--mk-ink-muted); }
.ring:not([data-seen]) .ringState { color: var(--pe-accent); }

.how { margin-top: 26px; }
.howHead { display: grid; gap: 4px; max-width: 56ch; }
.hints { display: grid; gap: 10px; margin: 14px 0 0; padding: 0; list-style: none; }
@container (min-width: 36rem) { .hints { grid-template-columns: repeat(2, minmax(0, 1fr)); } }
.hint {
  display: grid; grid-template-columns: 48px minmax(0, 1fr); align-items: center; gap: 14px; padding: 12px 14px 12px 12px;
  background: var(--mk-surface); border: 1px solid var(--mk-line); border-radius: var(--mk-radius-m); box-shadow: var(--pe-rest);
}
.hintArt { width: 48px; height: 62px; overflow: visible; filter: drop-shadow(1px 3px 3px rgb(var(--pe-shadow) / 0.25)); }
.hintPhone { fill: var(--pe-navy); }
.hintSeg { stroke: rgb(251 250 246 / 0.65); stroke-width: 2; stroke-linecap: round; }
.hintZone { fill: rgb(242 194 48 / 0.2); }
.hintZoneBack { fill: rgb(200 38 44 / 0.45); }
.hintTouch { fill: var(--pe-yellow); }
.hintRing { fill: none; stroke: var(--pe-yellow); stroke-width: 1.4; opacity: 0.55; }
.hintStroke { fill: none; stroke: var(--pe-paper); stroke-width: 2.4; stroke-linecap: round; stroke-linejoin: round; }
.hintTitle { margin: 0 0 3px; font-size: 0.9375rem; font-weight: 700; letter-spacing: -0.005em; }
.hintTwin { margin: 0; font-size: 0.8125rem; line-height: 1.6; color: var(--mk-ink-muted); }
.keyset { white-space: nowrap; }
.hintTwin kbd {
  display: inline-grid; place-items: center; min-width: 1.6em; height: 1.55em; padding: 0 5px; box-sizing: border-box; vertical-align: 0.05em;
