/* Reduced motion: nothing travels, scales or springs; the room changes colour without a blend. */
.root[data-reduced] :is(.ringArt, .headBtn, .cardBtn, .sendBtn, .accountBtn, .lightBtn, .peekCard, .viewerLayer) { transition: none; }
.root[data-reduced] .ring:is(:hover, :active) .ringArt, .root[data-reduced] :is(.headBtn, .accountBtn, .lightBtn, .sendBtn):is(:hover, :active) { transform: none; }
.root[data-reduced] .cardBtn:is(:hover, :active) { transform: translateY(-50%); }
